// FaleNetwork web tools inside the app: route #/web/<id>[?doc=<library id>].
// The tool page (wt-app/<lang>/<id>.html, generated by network/tools/webtools/build.py) runs in a same-origin frame;
// js/webtools/frame.js in that page talks to the host object below (window.__faleWtHost):
//   save(outputs)      results → the app's file library (PDF, Office, text, images) or – other formats (ZIP, SVG, VCF …)
//                      – saved to the device like the app's own downloads
//   share(outputs)     system share sheet (several files as one ZIP)
//   pickDocs(opts)     choose files from the library (only kinds the tool accepts)
//   openTool(slug|id)  links to other tools stay in the app; openExternal(url) asks before leaving the app
import { WEB_TOOLS } from './catalog.js';
import { webToolById, webToolText, acceptsDoc, docMime } from './list.js';
import { openScreen } from '../screen.js';
import { toast } from '../ui.js';
import { lang } from '../i18n/index.js';
import * as db from '../db.js';

// ---------------------------------------------------------------- hand-off into the frame
// Same store as network/assets/wt/lib/handoff.js ("fale-wt" / "handoff" / "current"): the tool page takes the files
// when it is opened with ?weiter=1 (de) / ?continue=1 (en).
function putHandoff(files, target) {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open('fale-wt', 1);
    req.onupgradeneeded = () => { if (!req.result.objectStoreNames.contains('handoff')) req.result.createObjectStore('handoff'); };
    req.onerror = () => reject(req.error);
    req.onblocked = () => reject(new Error('IndexedDB blocked'));
    req.onsuccess = () => {
      const idb = req.result;
      const tx = idb.transaction('handoff', 'readwrite');
      tx.objectStore('handoff').put({ files, target, from: 'fale-pdf-app', ts: Date.now() }, 'current');
      tx.oncomplete = () => { idb.close(); resolve(); };
      tx.onerror = () => { idb.close(); reject(tx.error); };
    };
  });
}

// ---------------------------------------------------------------- results
const own = async b => new Blob([await b.arrayBuffer()], { type: b.type || '' }); // copy into the app's realm

async function saveOutputs(outputs) {
  const [{ importAny }, { detectKind }, P] = await Promise.all([import('../library.js'), import('../office/kinds.js'), import('../platform.js')]);
  const docs = [];
  let device = 0;
  for (const o of outputs || []) {
    if (!o || !o.blob) continue;
    const blob = await own(o.blob);
    const name = String(o.name || 'Datei');
    const file = new File([blob], name, { type: blob.type });
    if (detectKind(file) && !(blob.type === 'image/svg+xml' || /\.svg$/i.test(name))) {
      try { docs.push(await importAny(file, { name, source: 'Erstellt', silent: true })); continue; } catch (e) { console.warn('web tool → library', String(e && (e.userMessage || e.message) || e)); }
    }
    const r = await P.saveFile(blob, name, blob.type || 'application/octet-stream');
    if (r && r.ok) device++;
  }
  if (docs.length === 1) {
    const { openHash } = await import('../office/kinds.js');
    toast(`„${docs[0].name}“ in deinen Dateien gespeichert`, 'success', { timeout: 6000, action: { label: 'Öffnen', onClick: () => { location.hash = openHash(docs[0]); } } });
  } else if (docs.length > 1) {
    toast(`${docs.length} Dateien in deinen Dateien gespeichert`, 'success', { timeout: 6000, action: { label: 'Anzeigen', onClick: () => { location.hash = '#/dateien'; } } });
  }
  return { library: docs.length, device };
}

async function shareOutputs(outputs, title) {
  const list = (outputs || []).filter(o => o && o.blob);
  if (!list.length) return 'failed';
  const P = await import('../platform.js');
  let blob, name;
  if (list.length === 1) {
    blob = await own(list[0].blob);
    name = list[0].name;
  } else {
    const { createZip } = await import('../zip.js');
    const files = await Promise.all(list.map(async o => ({ name: o.name, data: new Uint8Array(await o.blob.arrayBuffer()) })));
    blob = new Blob([await createZip(files)], { type: 'application/zip' });
    name = `${String(title || 'Dateien').replace(/[\\/:*?"<>|]+/g, ' ').trim() || 'Dateien'}.zip`;
  }
  const r = await P.shareFile(blob, name, blob.type || 'application/octet-stream', { title: title || name, silent: true });
  return r && r.ok ? 'shared' : r && r.cancelled ? 'aborted' : r && r.method === 'download' ? 'shared' : 'failed';
}

function canShareHere() {
  try {
    if (window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform()) return true;
    return !!(navigator.share && navigator.canShare && navigator.canShare({ files: [new File(['x'], 'x.pdf', { type: 'application/pdf' })] }));
  } catch { return false; }
}

async function pickDocs({ accepts, multiple, title } = {}) {
  const { pickDocsDialog } = await import('../components.js');
  const all = await db.listDocs();
  const exclude = all.filter(d => !acceptsDoc(d, accepts)).map(d => d.id);
  if (exclude.length === all.length && all.length) toast('In deinen Dateien ist noch nichts, das dieses Werkzeug öffnen kann.', 'info', { timeout: 5000 });
  const ids = await pickDocsDialog({ multi: !!multiple, title: title || 'Dateien wählen', exclude });
  if (!ids || !ids.length) return [];
  const out = [];
  for (const id of ids) {
    const meta = await db.getDoc(id);
    const blob = meta && await db.getFile(id);
    if (!blob) continue;
    if (!acceptsDoc(meta, accepts)) { toast(`„${meta.name}“ passt nicht zu diesem Werkzeug.`, 'error'); continue; }
    out.push({ name: meta.name, type: docMime(meta).replace('/*', '/png'), buffer: await blob.arrayBuffer() });
  }
  return out;
}

// ---------------------------------------------------------------- screen
const bySlug = slug => WEB_TOOLS.find(t => t.id === slug || t.de.slug === slug || t.en.slug === slug) || null;

export function webToolUrl(t, { handoff = false } = {}) {
  const l = lang() === 'en' ? 'en' : 'de';
  return `/wt-app/${l}/${t.id}.html${handoff ? (l === 'en' ? '?continue=1' : '?weiter=1') : ''}`;
}

export async function openWebToolRoute(parts, params, { goBack } = {}) {
  const t = webToolById(parts[1]) || bySlug(parts[1]);
  if (!t) { location.replace('#/werkzeuge'); return; }
  const txt = webToolText(t);
  const screen = openScreen({ title: txt.name, sub: txt.short || '', onBack: goBack });
  screen.hashKey = location.hash;
  screen.body.classList.add('wt-host-body');
  let handoff = false;
  const docId = params && params.get('doc');
  if (docId) {
    try {
      const meta = await db.getDoc(docId);
      const blob = meta && await db.getFile(docId);
      if (meta && blob && acceptsDoc(meta, t.accepts)) {
        await putHandoff([{ name: meta.name, type: docMime(meta).replace('/*', '/png'), blob }], t.id);
        handoff = true;
      } else if (meta) toast(`„${meta.name}“ passt nicht zu „${txt.name}“.`, 'error');
    } catch (e) { console.warn('web tool hand-off', e); }
    if (screen.signal.aborted) return;
  }
  const frame = document.createElement('iframe');
  frame.className = 'wt-host-frame';
  frame.title = txt.name;
  frame.setAttribute('allow', 'camera; clipboard-read; clipboard-write');
  const host = {
    save: outputs => saveOutputs(outputs).catch(e => { console.warn(e); toast('Speichern hat nicht geklappt.', 'error'); }),
    share: (outputs, title) => shareOutputs(outputs, title).catch(() => 'failed'),
    canShare: canShareHere,
    pickDocs,
    openTool: slug => {
      const next = bySlug(slug);
      if (next) location.hash = `#/web/${next.id}`;
    },
    openExternal: href => import('../security.js').then(S => S.openExternal(href, { source: txt.name + ':' })),
    frameReady: win => {
      // „Weiter mit …“ inside the frame opens the next tool: keep the header in sync
      try {
        const cfg = JSON.parse(win.document.getElementById('wt-config').textContent);
        const cur = webToolById(cfg.id);
        if (cur && cur.id !== t.id) { const x = webToolText(cur); screen.setTitle(x.name, x.short || ''); frame.title = x.name; }
        // the tool's shell marks the page when it runs (native consoles only see the app frame: log it here)
        const t0 = Date.now();
        const poll = () => {
          let ok = false;
          try { ok = win.document.documentElement.classList.contains('wt-js'); } catch { return; }
          if (ok) console.info(`FaLe Web-Werkzeug bereit: ${cfg.id}`);
          else if (Date.now() - t0 < 20000 && !screen.signal.aborted) setTimeout(poll, 250);
          else if (!screen.signal.aborted) console.warn(`FaLe Web-Werkzeug startet nicht: ${cfg.id}`);
        };
        poll();
      } catch { /* page without config */ }
    },
  };
  window.__faleWtHost = host;
  screen.cleanup = () => { if (window.__faleWtHost === host) delete window.__faleWtHost; };
  frame.src = webToolUrl(t, { handoff });
  screen.body.appendChild(frame);
}
